{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Dexetimide, a high-transfer analogue, is explicitly described as having good brain penetration suitable for PET neuroreceptor imaging, supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "In mice, the radioligand showed a brain-to-blood ratio of 2.2 rising to 6.3, confirming ready passage across the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "In vivo brain uptake reached 3.4% injected dose per gram of tissue and labeled sigma1 receptor-rich brain regions, demonstrating functional brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Planar imaging in monkeys showed significant accumulation of radioactivity in the brain, supporting CNS access in a higher species.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Brain tissue concentrations were 10-20% of blood concentrations with detectable accumulation after both administration routes, indicating meaningful BBB passage.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental records consistently demonstrate direct in vivo brain uptake and BBB permeability, with no contradictory evidence; therefore the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct query-specific pharmacokinetic measurements are available.",
    "Unbound brain or CSF concentrations were not reported for the query.",
    "Potential efflux transporter involvement was not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

